"""Random sequences of stack operations, weighted towards pushing
duplicate and negative values so the minimum-tracking tie case is
exercised often. Never pops, reads top, or reads the minimum on an
empty stack."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    ops = []
    depth = 0
    recent = []
    n_ops = rng.randint(4, 20)
    for _ in range(n_ops):
        choices = ["PUSH"]
        if depth > 0:
            choices += ["POP", "TOP", "GETMIN"]
        op = rng.choice(choices)
        if op == "PUSH":
            if recent and rng.random() < 0.35:
                value = rng.choice(recent)
            else:
                value = rng.randint(-10, 10)
            ops.append("PUSH %d" % value)
            recent.append(value)
            depth += 1
        elif op == "POP":
            ops.append("POP")
            depth -= 1
        else:
            ops.append(op)
    lines = [str(len(ops))] + ops
    return {"name": "a random sequence of %d stack operations #%d"
                    % (len(ops), index),
            "stdin": "\n".join(lines) + "\n"}
